"""
The frontend page, as a Python string constant instead of a separate
static file -- served directly by Flask so it never depends on Vercel
correctly auto-detecting a public/ directory as static output.
"""
INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>MPPL Bills</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Zilla+Slab:wght@500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@500;600&display=swap" rel="stylesheet">\n<style>\n  :root {\n    --paper: #efe9dd;\n    --paper-raised: #faf7f0;\n    --ink: #211e1a;\n    --ink-soft: #6b6255;\n    --line: #d9cfbb;\n    --line-strong: #b9ab8d;\n\n    --stamp-ink: #3e3465;\n    --stamp-ink-soft: #e9e5f0;\n\n    --paid: #2f6f4f;\n    --paid-wash: #e4efe6;\n    --pending: #a6672b;\n    --pending-wash: #f6e9db;\n\n    --serif: \'Zilla Slab\', Georgia, serif;\n    --sans: \'Inter\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Helvetica, Arial, sans-serif;\n    --mono: \'JetBrains Mono\', \'SFMono-Regular\', Consolas, monospace;\n  }\n  * { box-sizing: border-box; }\n  body {\n    margin: 0;\n    font-family: var(--sans);\n    background: var(--paper);\n    color: var(--ink);\n    -webkit-font-smoothing: antialiased;\n    background-image:\n      linear-gradient(var(--line) 1px, transparent 1px);\n    background-size: 100% 42px;\n    background-attachment: local;\n  }\n\n  header {\n    padding: 36px 40px 26px;\n    border-bottom: 3px double var(--line-strong);\n    background: var(--paper);\n    display: flex;\n    align-items: flex-end;\n    justify-content: space-between;\n    gap: 24px;\n    flex-wrap: wrap;\n  }\n  .wordmark {\n    display: flex;\n    align-items: baseline;\n    gap: 12px;\n  }\n  .wordmark .folio {\n    font-family: var(--mono);\n    font-size: 11px;\n    color: var(--ink-soft);\n    border: 1px solid var(--line-strong);\n    padding: 2px 6px;\n    border-radius: 3px;\n    transform: translateY(-2px);\n  }\n  header h1 {\n    margin: 0;\n    font-family: var(--serif);\n    font-weight: 700;\n    font-size: 26px;\n    letter-spacing: -0.01em;\n  }\n  header p {\n    margin: 6px 0 0;\n    color: var(--ink-soft);\n    font-size: 13.5px;\n    max-width: 46ch;\n  }\n\n  main {\n    max-width: 1040px;\n    margin: 0 auto;\n    padding: 36px 40px 72px;\n  }\n\n  section {\n    background: var(--paper-raised);\n    border: 1px solid var(--line);\n    border-radius: 3px;\n    box-shadow: 0 1px 0 var(--line);\n    padding: 26px 28px;\n    margin-bottom: 26px;\n  }\n  section > h2 {\n    margin: 0 0 16px;\n    font-family: var(--serif);\n    font-weight: 600;\n    font-size: 15px;\n    color: var(--ink);\n    padding-bottom: 10px;\n    border-bottom: 1px solid var(--line);\n  }\n\n  .dropzone {\n    border: 1.5px dashed var(--line-strong);\n    border-radius: 2px;\n    padding: 30px;\n    text-align: center;\n    color: var(--ink-soft);\n    cursor: pointer;\n    transition: border-color 0.15s, background 0.15s;\n    font-size: 14px;\n  }\n  .dropzone:hover, .dropzone.drag {\n    border-color: var(--stamp-ink);\n    background: var(--stamp-ink-soft);\n    color: var(--ink);\n  }\n  .dropzone input { display: none; }\n\n  .upload-row {\n    display: flex;\n    gap: 10px;\n    margin-top: 16px;\n    align-items: center;\n    flex-wrap: wrap;\n  }\n  input[type=text], input[type=email], select {\n    font-family: var(--sans);\n    font-size: 13.5px;\n    padding: 9px 11px;\n    border: 1px solid var(--line-strong);\n    border-radius: 2px;\n    background: #fff;\n    color: var(--ink);\n  }\n  input:focus, select:focus, button:focus-visible {\n    outline: 2px solid var(--stamp-ink);\n    outline-offset: 1px;\n  }\n  button {\n    font-family: var(--sans);\n    font-size: 13.5px;\n    font-weight: 600;\n    padding: 9px 18px;\n    border-radius: 2px;\n    border: 1px solid var(--stamp-ink);\n    background: var(--stamp-ink);\n    color: white;\n    cursor: pointer;\n  }\n  button:hover { background: #352c57; }\n  button:disabled { opacity: 0.45; cursor: default; }\n  button.ghost {\n    background: transparent;\n    color: var(--stamp-ink);\n    border: 1px solid var(--line-strong);\n    padding: 6px 12px;\n    font-size: 12.5px;\n  }\n  button.ghost:hover { border-color: var(--stamp-ink); background: var(--stamp-ink-soft); }\n\n  #upload-status { font-size: 13px; margin-top: 12px; min-height: 18px; font-family: var(--mono); }\n  #upload-status.ok { color: var(--paid); }\n  #upload-status.err { color: #96321e; }\n  @keyframes stamp-in {\n    0%   { transform: scale(1.4) rotate(-6deg); opacity: 0; }\n    60%  { transform: scale(0.96) rotate(1deg); opacity: 1; }\n    100% { transform: scale(1) rotate(0deg); opacity: 1; }\n  }\n  #upload-status.ok { animation: stamp-in 0.32s cubic-bezier(.2,.9,.3,1.3); transform-origin: left center; }\n\n  .filters { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }\n\n  table { width: 100%; border-collapse: collapse; font-size: 13.5px; }\n  th {\n    text-align: left;\n    font-family: var(--serif);\n    font-weight: 600;\n    color: var(--ink-soft);\n    font-size: 12.5px;\n    padding: 8px 10px 10px;\n    border-bottom: 2px solid var(--line-strong);\n  }\n  td { padding: 12px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }\n  tr:last-child td { border-bottom: none; }\n  tr:hover td { background: #f3ede0; }\n  td.num { font-family: var(--mono); font-weight: 500; font-variant-numeric: tabular-nums; text-align: right; }\n  td.inv { font-family: var(--mono); font-size: 12.5px; color: var(--ink-soft); }\n\n  .stamp {\n    display: inline-block;\n    font-family: var(--serif);\n    font-variant: small-caps;\n    font-weight: 600;\n    font-size: 12.5px;\n    letter-spacing: 0.03em;\n    padding: 2px 10px;\n    border: 1.5px solid currentColor;\n    border-radius: 3px;\n    transform: rotate(-2deg);\n  }\n  .stamp.paid, .stamp.confirmed { color: var(--paid); background: var(--paid-wash); }\n  .stamp.unpaid, .stamp.unknown, .stamp.pending_review, .stamp.partially_paid {\n    color: var(--pending); background: var(--pending-wash); transform: rotate(1.5deg);\n  }\n\n  a.filelink { color: var(--stamp-ink); text-decoration: none; font-size: 12.5px; font-weight: 500; }\n  a.filelink:hover { text-decoration: underline; }\n  #empty { color: var(--ink-soft); font-size: 13.5px; padding: 26px 0; text-align: center; font-family: var(--serif); }\n\n  @media (max-width: 640px) {\n    header, main { padding-left: 20px; padding-right: 20px; }\n    table, thead, tbody, th, td, tr { display: block; }\n    thead { display: none; }\n    tr { border-bottom: 1px solid var(--line); padding: 10px 0; }\n    td { border: none; padding: 3px 0; }\n    td.num { text-align: left; }\n  }\n</style>\n</head>\n<body>\n\n<header>\n  <div>\n    <div class="wordmark">\n      <h1>MPPL Bills</h1>\n      <span class="folio">Ledger</span>\n    </div>\n    <p>Upload a bill — it\'s read, filed to Drive, and entered into the ledger automatically.</p>\n  </div>\n</header>\n\n<main>\n  <section>\n    <h2>Upload</h2>\n    <div class="dropzone" id="dropzone">\n      <div id="dropzone-label">Drop a bill here (JPG, PNG, or PDF) — or click to choose a file</div>\n      <input type="file" id="file-input" accept=".jpg,.jpeg,.png,.pdf">\n    </div>\n    <div class="upload-row">\n      <input type="email" id="uploaded-by" placeholder="your email">\n      <button id="upload-btn" disabled>Upload &amp; extract</button>\n    </div>\n    <div id="upload-status"></div>\n  </section>\n\n  <section>\n    <h2>Bills</h2>\n    <div class="filters">\n      <input type="text" id="f-vendor" placeholder="Search vendor…">\n      <select id="f-payment">\n        <option value="">Any payment status</option>\n        <option value="paid">Paid</option>\n        <option value="unpaid">Unpaid</option>\n        <option value="partially_paid">Partially paid</option>\n        <option value="unknown">Unknown</option>\n      </select>\n      <select id="f-review">\n        <option value="">Any review status</option>\n        <option value="pending_review">Pending review</option>\n        <option value="confirmed">Confirmed</option>\n      </select>\n      <button class="ghost" id="refresh-btn">Refresh</button>\n    </div>\n    <table id="bills-table">\n      <thead>\n        <tr>\n          <th>Vendor</th><th>Invoice</th><th>Date</th><th style="text-align:right">Amount</th>\n          <th>Payment</th><th>Review</th><th>File</th><th></th>\n        </tr>\n      </thead>\n      <tbody id="bills-body"></tbody>\n    </table>\n    <div id="empty" style="display:none">No bills match those filters yet.</div>\n  </section>\n</main>\n\n<script>\nconst dropzone = document.getElementById(\'dropzone\');\nconst fileInput = document.getElementById(\'file-input\');\nconst dzLabel = document.getElementById(\'dropzone-label\');\nconst uploadBtn = document.getElementById(\'upload-btn\');\nconst uploadedByInput = document.getElementById(\'uploaded-by\');\nconst statusEl = document.getElementById(\'upload-status\');\n\nlet selectedFile = null;\n\ndropzone.addEventListener(\'click\', () => fileInput.click());\ndropzone.addEventListener(\'dragover\', e => { e.preventDefault(); dropzone.classList.add(\'drag\'); });\ndropzone.addEventListener(\'dragleave\', () => dropzone.classList.remove(\'drag\'));\ndropzone.addEventListener(\'drop\', e => {\n  e.preventDefault();\n  dropzone.classList.remove(\'drag\');\n  if (e.dataTransfer.files.length) setFile(e.dataTransfer.files[0]);\n});\nfileInput.addEventListener(\'change\', () => { if (fileInput.files.length) setFile(fileInput.files[0]); });\n\nfunction setFile(f) {\n  selectedFile = f;\n  dzLabel.textContent = `Selected: ${f.name}`;\n  uploadBtn.disabled = false;\n}\n\nuploadBtn.addEventListener(\'click\', async () => {\n  if (!selectedFile) return;\n  const uploadedBy = uploadedByInput.value.trim() || \'unknown\';\n\n  uploadBtn.disabled = true;\n  statusEl.className = \'\';\n  statusEl.textContent = \'Reading and filing the bill — this takes a few seconds…\';\n\n  const form = new FormData();\n  form.append(\'file\', selectedFile);\n  form.append(\'uploaded_by\', uploadedBy);\n\n  try {\n    const res = await fetch(\'/api/upload\', { method: \'POST\', body: form });\n    const data = await res.json();\n    if (!res.ok) throw new Error(data.error || \'Upload failed\');\n\n    statusEl.className = \'ok\';\n    statusEl.textContent = `Filed — ${data.extracted.vendor_name}, ₹${data.extracted.amount ?? \'?\'}. Pending review.`;\n    selectedFile = null;\n    fileInput.value = \'\';\n    dzLabel.textContent = \'Drop a bill here (JPG, PNG, or PDF) — or click to choose a file\';\n    loadBills();\n  } catch (err) {\n    statusEl.className = \'err\';\n    statusEl.textContent = err.message;\n  } finally {\n    uploadBtn.disabled = false;\n  }\n});\n\nconst body = document.getElementById(\'bills-body\');\nconst emptyEl = document.getElementById(\'empty\');\n\nfunction stamp(text, cls) {\n  return `<span class="stamp ${cls}">${text.replace(\'_\', \' \')}</span>`;\n}\n\nasync function loadBills() {\n  const params = new URLSearchParams();\n  const vendor = document.getElementById(\'f-vendor\').value.trim();\n  const payment = document.getElementById(\'f-payment\').value;\n  const review = document.getElementById(\'f-review\').value;\n  if (vendor) params.set(\'vendor\', vendor);\n  if (payment) params.set(\'payment_status\', payment);\n  if (review) params.set(\'review_status\', review);\n\n  const res = await fetch(\'/api/bills?\' + params.toString());\n  const rows = await res.json();\n\n  body.innerHTML = \'\';\n  emptyEl.style.display = rows.length ? \'none\' : \'block\';\n\n  for (const r of rows) {\n    const tr = document.createElement(\'tr\');\n    const amount = r.amount != null ? Number(r.amount).toLocaleString(\'en-IN\', { minimumFractionDigits: 2 }) : \'—\';\n    tr.innerHTML = `\n      <td>${r.vendor_name || \'\'}</td>\n      <td class="inv">${r.invoice_no || \'—\'}</td>\n      <td>${r.invoice_date || \'—\'}</td>\n      <td class="num">${amount}</td>\n      <td>${stamp(r.payment_status || \'unknown\', r.payment_status || \'unknown\')}</td>\n      <td>${stamp(r.review_status || \'pending_review\', r.review_status || \'pending_review\')}</td>\n      <td>${r.drive_link ? `<a class="filelink" href="${r.drive_link}" target="_blank">Open</a>` : \'—\'}</td>\n      <td>${r.review_status === \'pending_review\' ? `<button class="ghost" data-id="${r.id}">Confirm</button>` : \'\'}</td>\n    `;\n    body.appendChild(tr);\n  }\n\n  body.querySelectorAll(\'button[data-id]\').forEach(btn => {\n    btn.addEventListener(\'click\', async () => {\n      const id = btn.getAttribute(\'data-id\');\n      const confirmedBy = uploadedByInput.value.trim() || \'unknown\';\n      await fetch(\'/api/confirm\', {\n        method: \'POST\',\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify({ id: Number(id), confirmed_by: confirmedBy }),\n      });\n      loadBills();\n    });\n  });\n}\n\ndocument.getElementById(\'refresh-btn\').addEventListener(\'click\', loadBills);\ndocument.getElementById(\'f-vendor\').addEventListener(\'keydown\', e => { if (e.key === \'Enter\') loadBills(); });\ndocument.getElementById(\'f-payment\').addEventListener(\'change\', loadBills);\ndocument.getElementById(\'f-review\').addEventListener(\'change\', loadBills);\n\nloadBills();\n</script>\n</body>\n</html>\n'